package com.delivery.platform.orders.application;
import com.delivery.platform.common.ApiException;import com.delivery.platform.identity.security.IdentityPrincipal;import com.delivery.platform.orders.domain.OrderModels.Cart;import org.junit.jupiter.api.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThatThrownBy;import static org.mockito.Mockito.*;
class OrdersServiceTest {private final OrdersRepository repository=mock(OrdersRepository.class);private final OrdersService service=new OrdersService(repository);private final UUID tenant=UUID.randomUUID(),customer=UUID.randomUUID();private final IdentityPrincipal principal=new IdentityPrincipal(customer,tenant,"demo",Set.of(),Set.of());
 @Test void rejectsCheckoutWithEmptyCart(){Cart cart=new Cart(UUID.randomUUID(),customer,UUID.randomUUID(),UUID.randomUUID(),BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,BigDecimal.ZERO,"PEN","ACTIVE",List.of(),Instant.now(),Instant.now());when(repository.activeCart(tenant,customer)).thenReturn(Optional.of(cart));assertThatThrownBy(()->service.checkout(principal,UUID.randomUUID(),null)).isInstanceOf(ApiException.class).hasMessageContaining("Agrega al menos un producto");verify(repository,never()).createOrder(any(),any(),any(),any(),any(),any());}
}
